arguments.command:
python3 -c "
import pandas as pd
import re

df = pd.read_csv('b3_supercon_data.csv')

allowed = {'O', 'Cu', 'Ba', 'Sr', 'Y', 'Ca', 'La', 'Bi', 'Fe', 'Nb', 'C', 'Pr', 'As', 'B', 'Pb', 'Ce', 'Mo', 'V', 'Zn', 'Ni'}

def get_elements(comp):
    return set(re.findall(r'([A-Z][a-z]*)', comp))

for idx, row in df.sort_values('target', ascending=False).iterrows():
    elems = get_elements(row['composition'])
    if elems.issubset(allowed):
        print(f\"{row['composition']:30} {row['target']} {elems}\")
"

